package com.studyswap.service;
import com.studyswap.dto.BookRequest;import com.studyswap.entity.ListingType;import org.springframework.stereotype.Service;
@Service public class ListingRules {public void validate(BookRequest b){if(b.listingType()==ListingType.SELL&&(b.sellingPrice()==null||b.sellingPrice().signum()<=0))throw new IllegalArgumentException("SELL listings require a positive selling price");if(b.listingType()==ListingType.RENT&&(b.rentalPrice()==null||b.rentalPrice().signum()<=0))throw new IllegalArgumentException("RENT listings require a positive daily rental price");if((b.listingType()==ListingType.DONATE||b.listingType()==ListingType.EXCHANGE)&&(b.sellingPrice()!=null||b.rentalPrice()!=null||b.securityDeposit()!=null))throw new IllegalArgumentException(b.listingType()+" listings cannot contain monetary values");}}
